with d as (select value r from jsonb_array_elements($q$[{"steps":[{"text":"Heat the sesame oil in a large wok or wide frying pan over medium-high heat."},{"text":"Add the zucchini and salt. Stir-fry, tossing gently and frequently, until the zucchini is tender but still holds its shape and the edges are lightly caramelised, about 6–8 minutes. The zucchini will release a little moisture; let it cook off."},{"text":"Remove from the heat and allow to cool for a minute. Add the perilla leaves and toss gently to combine."},{"text":"Transfer to a serving bowl, scatter with the sesame seeds and black pepper, and serve at room temperature or slightly warm."}],"id":"6cf870e1-c10d-4f1e-9938-6d33defc9dae"},{"steps":[{"text":"Dice the tomatoes into small, even pieces, about the size of a pea. If they release a lot of juice, drain them slightly."},{"text":"Dice the white onion into small pieces the same size as the tomato."},{"text":"Chop the fresh coriander roughly, then go over it once more with the knife so it's fine."},{"text":"Combine the tomato, onion and coriander in a bowl."},{"text":"Squeeze the lime juice over, add a pinch of salt, and stir gently until the tomato is glossy and lightly coated in juice. Taste and adjust salt and lime."},{"text":"Serve right away, or cover and keep in the fridge for up to an hour."}],"id":"1b7a0a26-a44c-4fbd-a1fe-5315867743f6"},{"notes":["Make the broth ahead and reheat gently; it keeps for 3 days in the fridge. Cook the noodles fresh just before serving.","No fresh crab? Use a good tinned crab in brine (drain well), or substitute more crab paste with a little extra stock to thin it.","The fried shallots are worth finding at any Vietnamese or Asian grocer, they're the difference between good and the stall version.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"d26e8327-44fd-4cce-9850-5fc4adbf165e"},{"notes":["Marinate the chicken overnight for best flavour, it's worth the patience.","Use bone-in, skin-on chicken; it stays juicier and develops that crackling skin Yogyakarta style.","Serve at room temperature with steamed rice and sambal if you like heat.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"id":"7d22dab0-a9fe-48d2-a5ca-39bd13cf6f2b"},{"notes":["Snapper is the go-to, firm, sweet, cooks quickly. Sub any fresh white fish fillet.","Make it vegetarian: swap the fish for 250 g firm tofu, cut into thick slices, pan-seared until golden.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"id":"01b02dd2-4251-4de7-bca0-1e1bb49a8e1b"},{"notes":["Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"id":"ee03b726-032d-4ecd-9ff5-57319a904d34"},{"notes":["Fresh molokhia is best and usually the cheapest; dried molokhia works too, use half the weight and crush it into a powder before adding. Frozen molokhia is also fine.","If you can't find molokhia, spinach is the closest substitute, though it's leafier and less slimy. Don't overcook spinach or it falls apart.","The stew thickens as it cools; add a splash more stock when reheating if needed."],"steps":[{"text":"Bring the vegetable stock to a boil in a large pot, until it bubbles steadily."},{"text":"Add the chopped molokhia leaves and stir to combine. Simmer for 5 minutes until the leaves start to break down."},{"text":"While the molokhia simmers, heat a tablespoon of oil in a small pan over medium heat. Add the chopped garlic and fry gently, stirring often, until golden and fragrant, about 3 minutes."},{"text":"Crush the fried garlic with the salt using the back of a spoon or a mortar and pestle until it forms a paste."},{"text":"Stir the garlic paste and ground coriander into the molokhia. Simmer for a further 3 to 5 minutes until the stew is thick and cohesive."},{"text":"Serve the molokhia over a bed of steamed rice, with lemon wedges on the side for squeezing."}],"id":"b491b07d-d5fe-489b-a794-302671fec1cf"},{"steps":[{"text":"Rinse the yellow split peas under cold water, then tip into a large pot with the water and quartered brown onion. Bring to a boil, then reduce the heat and simmer gently, uncovered, for about 50 minutes, stirring often, until the peas have broken down completely into a thick purée."},{"text":"When the peas are very soft and falling apart, remove from the heat and discard the onion pieces. Season generously with salt."},{"text":"Whisk in the olive oil, a little at a time, beating to incorporate air and make the purée smooth and pale. This will take 3–4 minutes of steady whisking."},{"text":"Stir in the lemon juice, then taste and adjust the seasoning, you want salt, brightness and richness in balance."},{"text":"Divide among four bowls and top each with a handful of raw red onion slices and a crack of black pepper. Serve warm or at room temperature."}],"id":"8c512d47-9cb7-4093-8f12-2f2f2ad73bea"},{"notes":["If you can't find ready-made tarhana paste, you can order it online. Turkish delis often stock it.","Tarhana keeps for months in an airtight jar, so it's worth having on hand.","A dollop of yoghurt stirred in at the end is traditional, use about 1 tbsp per bowl.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"id":"75d6ab6d-b413-4e95-8003-9da5e2bc2126"},{"steps":[{"text":"If using a whole coconut, pierce the eyes and drain the liquid. Crack open the shell and peel away the brown skin with a vegetable peeler. Grate the white flesh on a fine grater or microplane until you have about 400 g of fine, fluffy coconut."},{"text":"Put the grated coconut into a bowl and add the lime juice, chopped chillies, pounded dried fish, and red onion."},{"text":"Mix gently but thoroughly until every grain of coconut is coated and the flavours are even."},{"text":"Taste and adjust the seasoning with salt. The sambol should be bright, sharp, and hot, not timid."},{"text":"Serve immediately alongside hot rice and curry."}],"id":"b8128269-ec85-43bf-9dbc-7edc93d7253b"},{"notes":["Make the filling and dough ahead: the filling keeps for 2 days in the fridge, and the dough keeps for up to 4 hours. You can freeze uncooked pierogi on a tray, then boil them straight from frozen (add 1 extra minute to the boiling time).","A potato ricer or food mill makes a smoother filling if you don't like lumps, though a rustic texture is traditional too.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Make the dough: mix flour and salt in a bowl. In another bowl, whisk the egg, then stir in the sour cream. Pour the wet mixture into the flour and mix until you have a soft, slightly sticky dough. Knead for 5 minutes until smooth and elastic. Cover and rest for 30 minutes."},{"text":"Meanwhile, make the filling: boil the potato pieces in salted water until very tender, about 12 minutes. Drain well and mash roughly, you want some small lumps. Fry the chopped onion in 2 tbsp butter over medium heat until soft and golden, about 5 minutes. Stir the onion and butter into the potato, then fold in the cheese. Season to taste with salt and pepper. Let cool."},{"text":"Make the caramelized onions for serving: slice the 2 onions thinly. Melt 3 tbsp butter in a wide pan over medium heat and cook the onions, stirring often, until they're golden and soft, about 15 minutes. Set aside."},{"text":"Roll the pierogi: flour your work surface lightly. Roll the dough out to about 2 mm thick. Using a 7 cm round cutter or a glass, cut out circles. Place a heaped teaspoon of filling on each circle, fold in half, then press the edges to seal, fold the corner of the half-moon up and over itself to make a small curved seal (this is the traditional shape). Oil your hands if the dough sticks."},{"text":"Bring a large pot of salted water to a boil. Working in batches, drop the pierogi in. They'll sink at first, then float to the surface when they're nearly done, about 2 minutes. Boil for another 30 seconds after they float, then lift out with a slotted spoon."},{"text":"Serve the pierogi warm with the caramelized onions spooned over the top and a dollop of sour cream. Scatter with fresh dill if you like."}],"id":"c92a67ba-17c0-4c71-a6dc-63508785eb28"},{"notes":["The curry can be made a day ahead and reheated gently. The sambals are best made an hour or two before serving so the flavours meld.","Use leftover roast chicken or vegetables instead of making the curry, a generous spoonful stirred through the rice works just as well.","The rice can also be cooked in a rice cooker: fry the onion, garlic and ginger in a pot, add turmeric and rice to coat, then transfer to the rice cooker with the stock and bay leaves.","Cook mince and sausages until they reach 75°C in the centre, with no pink left.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"id":"81de07e0-e8d4-40c9-addf-f77c7f6e58c9"},{"notes":["Make this a day ahead: the pralines soften beautifully overnight and the flavours deepen.","Pink pralines are a Lyon specialty and worth hunting down in good delis or online. They're crunchy, delicately flavoured hazelnut pralines and not like anything else.","If your oven runs hot, tent the tart loosely with foil if it's browning too quickly.","Food safety: The eggs are cooked until just set. For pregnant women, young children, older people or anyone with a weakened immune system, cook them until firm all the way through."],"steps":[{"text":"Make the pastry: rub the cold butter into the flour with your fingertips until it looks like breadcrumbs, then stir in the caster sugar and salt. Beat the egg yolk with the cold water and mix into the flour until just combined. Form a disc, wrap in cling film and refrigerate for at least 30 minutes."},{"text":"Preheat the oven to 200°C. Roll out the pastry between two sheets of baking paper to about 3 mm thick. Press into a 24 cm tart tin, trim the edges and prick the base. Blind bake with baking paper and beans for 12 minutes, then remove the paper and beans and bake for another 5 minutes until just set. Set aside to cool slightly."},{"text":"Roughly crush about three-quarters of the pink pralines with the back of a spoon, you want some texture, not a smooth paste. Stir the softened butter through the crushed pralines."},{"text":"Whisk the cream, milk, egg yolks and vanilla together until smooth. Fold in the praline mixture, then pour into the cooled pastry shell. Scatter the remaining whole pralines over the top."},{"text":"Bake at 180°C for about 10 minutes, until the filling is just set but still trembling slightly in the centre. The tart will continue to set as it cools. Chill for at least 4 hours, or overnight, before serving."}],"id":"b74d0eae-b854-4fff-b755-71ba99553eb6"},{"notes":["The whole point is freshness and gentleness. Don't rush the poaching, low heat keeps the fish tender. If your fillets are very thick, give them an extra minute.","Brown butter can be made ahead and kept warm; reheat gently before serving.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Pour the stock or water into a wide, shallow pan and add the bay leaf. Bring to a gentle simmer over medium heat, until the surface is barely trembling with tiny bubbles and not boiling."},{"text":"Pat the fish fillets dry with paper towel and season lightly with salt on both sides."},{"text":"Slide the fish into the simmering stock. The liquid should barely cover them. Poach gently, the surface should barely tremble, for about 8 minutes, until the fish is cooked through and flakes easily when tested with a fork."},{"text":"Carefully lift the fish onto warm plates using a slotted spatula, leaving the poaching liquid behind."},{"text":"Melt the butter in a small pan over medium heat, swirling occasionally, until it turns a light golden brown and smells nutty, about 3 minutes. Watch it carefully so it doesn't burn."},{"text":"Drizzle the brown butter, which should smell nutty and be golden brown, over each fillet, which should be opaque and flake easily. Scatter the chives over the top, and finish with a grind of black pepper. Serve at once."}],"id":"7d15940a-33a0-4b5e-8a19-5c320c151852"},{"notes":["The dough keeps well: store finished pancakes in an airtight container for 2 days, then reheat briefly in a dry frying pan. You can also freeze uncooked rested discs for up to a month, then cook straight from frozen (add 2 minutes to the cooking time).","Hydration is key here, 75% feels sticky at first, but it's what gives you those delicate, shattering layers. Don't add extra flour."],"steps":[{"text":"Mix the boiling water into the flour and salt with a wooden spoon or chopsticks until shaggy. Let cool for 5 minutes, then knead by hand until smooth and soft, about 8 minutes. The dough will be slightly sticky, this is right. Cover with a damp cloth and rest for 20 minutes."},{"text":"Divide the dough into 4 equal pieces. Roll each piece into a ball, brush all over with a little oil, and rest for 10 minutes covered."},{"text":"On an oiled work surface, roll one ball into a thin rectangle about 30 cm × 20 cm. Brush generously with oil, scatter a quarter of the chopped spring onion evenly over the surface, then tightly roll up from one long edge into a log. Coil the log into a spiral, tucking the end underneath. Press gently to flatten slightly into a disc about 1 cm thick. Repeat with the remaining dough balls, spring onion and oil. Let rest for 5 minutes."},{"text":"Roll each disc into a round about 20 cm across, being gentle so the layers stay distinct. If the dough springs back, let it rest for a minute and try again."},{"text":"Heat 1½ tbsp oil in a large non-stick frying pan over medium heat. Once shimmering, place one pancake in and cook for 2–3 minutes until the underside is golden and crispy. Flip and cook the other side for 1–2 minutes until speckled and cooked through."},{"text":"Transfer to a plate and immediately sprinkle with a pinch of coarse sea salt. Repeat with the remaining pancakes, adding a little more oil to the pan as needed. Serve warm, torn into pieces."}],"id":"dca90649-8e17-452d-8c83-516cc2a998f6"},{"notes":["Keep in the fridge for up to 3 days and serve cold, or reheat gently in a 180°C oven.","No chilli in the house? Use a pinch of dried oregano instead, or just the onions. The frittata doesn't need much.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"786df343-cd47-4248-a178-7e5a1a725dd2"},{"notes":["Make it ahead: cook it the day before, cool quickly, and refrigerate in an airtight container for up to 3 days. Reheat gently in the pot with a splash of water.","This is Jamaican rice and peas, which uses kidney beans, not the peas you might find elsewhere in the Caribbean."],"steps":[{"text":"Pour the coconut milk into a large measuring jug and add water to make 600 ml total. Stir well to combine."},{"text":"Heat the oil in a heavy-bottomed pot over medium heat. Add the onion and cook, stirring, until softened and fragrant, about 3 minutes."},{"text":"Add the garlic and cook, stirring, for 1 minute more."},{"text":"Add the rice, stirring to coat in the oil, about 1 minute."},{"text":"Pour in the coconut milk mixture and stock, then add the kidney beans, thyme, salt and pepper. Stir well and bring to a boil until the liquid is bubbling steadily."},{"text":"Once boiling, reduce the heat to low, cover with a tight-fitting lid, and cook for 18 to 20 minutes, until the rice is tender and the liquid is absorbed. Do not lift the lid during cooking."},{"text":"Remove from the heat and let it rest, covered, for 2 minutes. Fluff with a fork, discard the thyme sprig if using fresh, and scatter with spring onion if you like."}],"id":"53b7958d-9eb9-43ae-b589-d853f67e777e"},{"diets":["pescatarian","no-gluten","no-dairy"],"notes":["Use good-quality fresh tuna; frozen won't give you the same result.","Don't stir too much once the tuna is in, you want to keep the chunks intact.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"764dbee9-eb81-4b2f-b23f-847c0701a0a0"},{"notes":["If you can't find millet, substitute with 150 g of pearl barley or extra rice, though the texture won't be quite the same.","Make it the night before and reheat gently with a splash of water, the flavour deepens overnight.","The best toppings are fried plantain, avocado slices, grated hard-boiled egg, and a spoonful of hot shito (pepper) sauce on the side."],"id":"14745b20-58d7-4f75-943a-561053a418cf"},{"notes":["The horseradish cream can be made up to 2 hours ahead and kept in the fridge.","Use the best smoked mackerel you can get, local fishmonger quality makes all the difference."],"id":"f3e06db8-1730-4aea-811d-4bec191708cd"},{"notes":["Make it the day before and refrigerate, it actually improves. Just add 10 minutes to the baking time if cooking from cold.","Lamb neck fillet works just as well as shoulder and gives you more flavour for the gravy.","Don't skip the second blast at high heat, that's what gets the potatoes crispy.","Food safety: Slow-cooked meat is safe once it is tender and the centre has reached at least 75°C."],"steps":[{"text":"Heat oven to 160°C. Layer half the potatoes in the bottom of a deep baking dish or casserole (about 2 litre capacity), then half the onions."},{"text":"Add all the lamb pieces, then layer the remaining onions and remaining potatoes on top, seasoning each layer with salt, pepper and thyme as you go."},{"text":"Warm the chicken stock and pour it over everything, it should come about three-quarters of the way up the dish. Dot the top with small pieces of butter."},{"text":"Cover tightly with foil and bake for 2 hours at 160°C, until the lamb is completely tender."},{"text":"Increase oven to 200°C, remove the foil, and bake uncovered for a further 15 minutes until the potato tops are golden and crispy."},{"text":"Rest for 5 minutes before serving. The gravy should come from the lamb and stock, you don't need to make it separately."}],"id":"2bc19133-3661-48e8-9436-ba8f4b38f66a"},{"notes":["Serve with torn bread to soak up the sauce.","Make the sauce ahead and reheat gently before poaching the eggs.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"2e8638db-c3f2-4b0b-ae97-f6eb1371a058"},{"notes":["Make this salad just before eating, if it sits too long, the vegetables release water and it becomes watery.","The dice should be fine and even. This isn't just cutting vegetables small; it's about texture, so every piece sits together in the bowl."],"steps":[{"text":"Dice the tomatoes into small, even pieces about the size of a pea, working over a bowl to catch the juice."},{"text":"Dice the cucumber to the same size as the tomato."},{"text":"Finely chop the parsley, removing the coarse stems and using mostly the leaves."},{"text":"Combine the tomato, cucumber and parsley in a bowl."},{"text":"Pour the lemon juice and olive oil over the vegetables and toss gently but thoroughly so everything is well coated."},{"text":"Taste and add salt until it's right, not too much, just enough to bring out the flavour of the vegetables."},{"text":"Serve straight away with warm bread to eat it with."}],"id":"af161dce-3949-4e13-b2bf-13c1ec905c57"},{"notes":["Thieboudienne can be made a day ahead: cook the fish and vegetables up to step 5, cool and refrigerate, then finish the rice and reheat gently before serving.","If you can't find a whole fish, use thick fish steaks (about 200g each) and add them after the rice has cooked for 15 minutes, so they don't break up.","The caramelized onion base is everything, don't rush it. The darker and deeper the onions, the better the dish.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"9a9feab9-a598-4b10-a9aa-dbdf04e56cdc"},{"notes":["The chicken liver must not be overcooked or it becomes tough. Add it back to the pot at the very end.","Fresh egg noodles cook much faster than dried; if using dried noodles, add them earlier and cook for 8–10 minutes.","The cornflour slurry must be stirred in slowly to avoid lumps.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"a6da6d2f-7381-4472-ac8f-f771d5904d72"},{"notes":["Beef ribs (short ribs or beef back ribs) cook beautifully the same way, just allow an extra 2–3 minutes per side.","No grill? A heavy cast-iron pan on the stove over high heat works. You won't get the same char, but the flavour will be there.","Best eaten straight off the heat with your flatmates and cold beers.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"steps":[{"text":"Heat your grill or barbecue to hot. If using charcoal, wait until the coals are white and glowing; if gas, get it smoking."},{"text":"Pat the beef dry with paper towel until the surface is no longer wet. This helps it char, not steam."},{"text":"Rub the meat lightly with oil, then season generously with salt on both sides."},{"text":"Lay the meat on the grill in a single layer. Don't move it for the first 4 minutes, you want a good char."},{"text":"Flip and cook the other side for another 4 minutes. The meat should have a dark crust but still be pink inside (about 55°C on a meat thermometer)."},{"text":"Transfer to a warm plate. Squeeze lime over the hot meat, it'll sizzle and the juice will run into all the crevices."},{"text":"Let it rest for 2 minutes, then serve with extra lime wedges and salt on the side for dipping."}],"id":"c0279693-c922-4670-8c65-1ad83d1abc92"},{"notes":["Use a rotisserie chicken from Coles if you don't have cooked chicken on hand, shred the meat, skip the skin.","Salsa verde comes in jars in most supermarkets (Coles has it). If you can't find it, blend canned green tomatoes (tomatillos) with a jalapeño, coriander, and lime juice.","Make ahead: assemble the dish, cover with foil, and refrigerate up to 24 hours. Bake for an extra 5 minutes if cooking from cold.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"id":"3f192f3c-8e9b-4c06-a4c8-07deb77c97ad"},{"notes":["Make the filling and dough a day ahead; chill separately. Roll and fold the morning of, then chill on the tray.","Freeze uncooked tortellini on a tray, then transfer to a freezer bag. Cook from frozen, adding 1–2 minutes to the simmer time.","The filling should taste bold, it seasons the broth. Don't be shy with salt, pepper, and nutmeg.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"steps":[{"text":"Make the pasta: mound flour on a bench, crack eggs into centre, add a pinch of salt. Work with a fork until shaggy, then knead by hand for 8–10 minutes until smooth and elastic. Wrap and rest 30 minutes."},{"text":"Make the filling: fry pork mince in a pan over medium heat, breaking it up, until it loses its colour, about 5 minutes. Cool completely, then mix with ham, parmesan, breadcrumbs, egg yolk, nutmeg, salt and pepper. Taste and adjust."},{"text":"Roll the pasta: divide dough into 4 pieces. Working with one at a time (keep others covered), roll very thin on a lightly floured surface, thin enough to read through. Using a 5 cm cutter or glass, cut circles."},{"text":"Fill and fold: place ½ tsp filling slightly off-centre on each circle. Fold in half to make a half-moon, press edges firmly. Bring the two points of the half-moon together to seal into a ring. Place on a tray lined with baking paper, well spaced. Repeat until done."},{"text":"Chill the tortellini on the tray, uncovered, for at least 30 minutes (or up to 4 hours before cooking)."},{"text":"Bring stock to a steady simmer in a large pot. Carefully drop in tortellini, a few at a time so the broth stays moving. They'll sink, then float to the surface; simmer for 2–3 minutes after they float."},{"text":"Serve in bowls with hot broth, grated parmesan, a crack of black pepper, and parsley if you like."}],"id":"7dbd2c96-e4b8-45bb-9540-b8fff11e379a"},{"notes":["Beef tongue keeps well raw for 2 days in the fridge, wrapped. Ask your butcher to slice it thin on the deli slicer, or freeze for an hour and slice yourself with a sharp knife.","Cooked tongue is best eaten fresh, but any leftovers are good cold the next day.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"id":"32cfe5a3-cafb-49fa-af7a-95728bef5eb2"},{"notes":["If you can't find fresh tamarind paste, use 1½ tbsp tamarind concentrate or 2 tbsp lime juice for a lighter sour note.","The herbs are not optional, they're what makes it sing. Vietnamese mint (laksa leaf) is traditional, but use whatever fresh herbs you have.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"id":"dda55326-2dd1-4129-a4d8-2336a3397614"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;